const items = $input.all();
const existingUrls = new Set();
const existingKeys = new Set();
for (const item of items) {
  const url = (item.json.job_url || '').toLowerCase().trim();
  if (url) existingUrls.add(url);
  const key = ((item.json.company || '') + '|||' + (item.json.job_title || '')).toLowerCase();
  if (key !== '|||') existingKeys.add(key);
}
$workflow.staticData.existingUrls = Array.from(existingUrls);
$workflow.staticData.existingKeys = Array.from(existingKeys);
$workflow.staticData.rejectedCount = { usOnly: 0, euOnly: 0, hybrid: 0, timezone: 0, other: 0 };
$workflow.staticData.todayJobs = [];
return [{ json: { initialized: true, existingCount: existingUrls.size, date: new Date().toISOString() } }];

const items = $input.all();
const normalized = [];

function cleanHtml(str) {
  if (!str) return '';
  return str.replace(/<[^>]*>/g, ' ').replace(/&amp;/g,'&').replace(/&lt;/g,'<').replace(/&gt;/g,'>').replace(/&nbsp;/g,' ').replace(/\s+/g,' ').trim();
}

function guessSource(d) {
  if (d._source) return d._source;
  if (d.position !== undefined && d.slug !== undefined) return 'Remote OK';
  if (d.candidate_required_location !== undefined) return 'Remotive';
  if (d.isRemote !== undefined && d.absoluteUrl !== undefined) return 'Himalayas';
  if (d.link !== undefined && d.pubDate !== undefined) return 'RSS Feed';
  if (d.job_url !== undefined) return 'Unknown';
  return 'Unknown';
}

for (const item of items) {
  const d = item.json;
  let job = null;

  // Handle array responses (Remote OK returns array, first item is meta)
  if (Array.isArray(d)) {
    for (const entry of d.slice(1)) {
      if (entry && entry.position) {
        normalized.push({ json: {
          job_id: `remoteok-${entry.id || entry.slug}`,
          job_title: entry.position || '',
          company: entry.company || '',
          job_url: entry.url || `https://remoteok.com/remote-jobs/${entry.slug}`,
          source: 'Remote OK',
          location_text: Array.isArray(entry.location) ? entry.location.join(', ') : (entry.location || 'Remote Worldwide'),
          salary: entry.salary || '',
          description: cleanHtml(entry.description || ''),
          posted_date: entry.date || new Date().toISOString(),
          tags: Array.isArray(entry.tags) ? entry.tags.join(', ') : '',
          date_found: new Date().toISOString()
        }});
      }
    }
    continue;
  }

  // Remotive format
  if (d.jobs && Array.isArray(d.jobs)) {
    for (const j of d.jobs) {
      normalized.push({ json: {
        job_id: `remotive-${j.id}`,
        job_title: j.title || '',
        company: j.company_name || '',
        job_url: j.url || '',
        source: 'Remotive',
        location_text: j.candidate_required_location || 'Remote Worldwide',
        salary: j.salary || '',
        description: cleanHtml(j.description || ''),
        posted_date: j.publication_date || new Date().toISOString(),
        tags: j.tags || '',
        date_found: new Date().toISOString()
      }});
    }
    continue;
  }

  // Himalayas jobs array
  if (d.jobs && Array.isArray(d.jobs) && d.jobs[0] && d.jobs[0].absoluteUrl) {
    for (const j of d.jobs) {
      normalized.push({ json: {
        job_id: `himalayas-${j.id || j.slug}`,
        job_title: j.title || j.jobTitle || '',
        company: (j.company && j.company.name) || j.companyName || '',
        job_url: j.absoluteUrl || j.url || '',
        source: 'Himalayas',
        location_text: (j.locationRestrictions || []).join(', ') || 'Remote Worldwide',
        salary: j.salaryRange ? `${j.salaryRange.min || ''}-${j.salaryRange.max || ''} ${j.salaryRange.currency || 'USD'}` : '',
        description: cleanHtml(j.content || j.description || ''),
        posted_date: j.createdAt || j.publishedAt || new Date().toISOString(),
        tags: Array.isArray(j.skills) ? j.skills.join(', ') : '',
        date_found: new Date().toISOString()
      }});
    }
    continue;
  }

  // RSS format (We Work Remotely, Dynamite Jobs via RSS)
  if (d.link !== undefined || d.pubDate !== undefined || d.guid !== undefined) {
    const source = guessSource(d);
    job = {
      job_id: `rss-${Date.now()}-${Math.random().toString(36).slice(2,7)}`,
      job_title: d.title || '',
      company: d.author || d['dc:creator'] || d.creator || '',
      job_url: d.link || d.guid || '',
      source: source,
      location_text: d.location || 'Remote',
      salary: '',
      description: cleanHtml(d.content || d['content:encoded'] || d.summary || d.description || ''),
      posted_date: d.pubDate || d.isoDate || new Date().toISOString(),
      tags: Array.isArray(d.categories) ? d.categories.join(', ') : (d.categories || ''),
      date_found: new Date().toISOString()
    };
  }

  // Generic object with job data
  else if (d.title || d.job_title) {
    job = {
      job_id: d.job_id || d.id || `generic-${Date.now()}-${Math.random().toString(36).slice(2,7)}`,
      job_title: d.job_title || d.title || d.name || '',
      company: d.company || d.company_name || d.organization || '',
      job_url: d.job_url || d.url || d.link || d.apply_url || '',
      source: guessSource(d),
      location_text: d.location_text || d.location || d.candidate_required_location || 'Remote',
      salary: d.salary || d.compensation || d.salary_range || '',
      description: cleanHtml(d.description || d.content || d.body || d.summary || ''),
      posted_date: d.posted_date || d.date || d.created_at || d.publication_date || new Date().toISOString(),
      tags: Array.isArray(d.tags) ? d.tags.join(', ') : (d.tags || d.skills || d.categories || ''),
      date_found: new Date().toISOString()
    };
  }

  if (job && job.job_title && job.job_url) {
    normalized.push({ json: job });
  }
}

return normalized;

const items = $input.all();
const ROLE_KEYWORDS = [
  'data analyst','data scientist','junior data scientist','business intelligence',
  'bi analyst','marketing analyst','performance marketing','growth analyst',
  'ai marketing','ai automation','ai workflow','creative strategist','martech',
  'analytics engineer','product analyst','revenue analyst','digital marketing',
  'growth hacker','marketing data','seo analyst','ppc analyst','sem','programmatic',
  'attribution analyst','customer analytics','sql analyst','tableau','power bi'
];
const REMOTE_KEYWORDS = [
  'async remote','asynchronous remote','worldwide remote','global remote',
  'work from anywhere','remote data','remote analyst','remote scientist',
  'remote marketing','remote growth','remote bi','remote automation','remote ai'
];
const ALL = [...new Set([...ROLE_KEYWORDS,...REMOTE_KEYWORDS])];

return items.filter(item => {
  const text = [
    item.json.job_title || '',
    (item.json.description || '').substring(0, 2000),
    item.json.tags || ''
  ].join(' ').toLowerCase();
  return ALL.some(kw => text.includes(kw));
});

const items = $input.all();
const existingUrls = new Set($workflow.staticData.existingUrls || []);
const existingKeys = new Set($workflow.staticData.existingKeys || []);
const seen = new Set();
const result = [];

for (const item of items) {
  const url = (item.json.job_url || '').toLowerCase().trim();
  const key = ((item.json.company || '') + '|||' + (item.json.job_title || '')).toLowerCase();
  if (!url) continue;
  if (existingUrls.has(url)) continue;
  if (key !== '|||' && existingKeys.has(key)) continue;
  if (seen.has(url)) continue;
  seen.add(url);
  result.push(item);
}
return result;

const items = $input.all();

const REJECT = [
  /\bus[\s-]?only\b/i, /\bunited[\s-]?states[\s-]?only\b/i,
  /\bcanada[\s-]?only\b/i, /\buk[\s-]?only\b/i,
  /\beu[\s-]?only\b/i, /\beurope[\s-]?only\b/i,
  /\baustralia[\s-]?only\b/i, /\bnew[\s-]?zealand[\s-]?only\b/i,
  /must\s*be\s*based\s*in/i, /must\s*(live|reside)\s*in/i,
  /must\s*be\s*authorized\s*to\s*work\s*in/i,
  /\blocal\s*work\s*permit\s*required\b/i,
  /\bhybrid\b/i, /\bon[\s-]?site\b/i, /\boffice[\s-]?(required|based)\b/i,
  /remote\s*(only\s*)?(in|within)\s*(the\s*)?(us|usa|uk|canada|eu|europe|australia)\b/i,
  /authorized\s*to\s*work\s*in\s*(the\s*)?(us|uk|canada|eu)/i,
  /must\s*be\s*(a\s*)?(us|uk|eu|canadian|australian)\s*(citizen|resident|national|pr)\b/i,
  /\bno\s*visa\s*sponsorship\b/i,
  /only\s*accept(ing)?\s*(candidates\s*)?(from|based\s+in)\s*(the\s*)?(us|usa|uk|canada|eu|europe)/i,
  /\bmidnight\s*(hours|shifts)\b/i,
  /fixed\s*(us|est|pst|cst|cet|cest)\s*hours\b/i
];

const KEEP = [
  /\bworldwide\b/i, /\bglobal\s*remote\b/i, /\bwork\s*from\s*anywhere\b/i,
  /\banywhere\s*in\s*the\s*world\b/i, /\bapac\b/i,
  /\binternational\s*contractors?\b/i, /\bb2b\s*contract(or|ing)?\b/i,
  /\bdeel\b/i, /\boyster\b/i, /\beor\b/i, /\bemployer\s*of\s*record\b/i,
  /hires?\s*(via|through|using)\s*(deel|remote\.com|oyster)/i
];

const rc = $workflow.staticData.rejectedCount || { usOnly:0, euOnly:0, hybrid:0, timezone:0, other:0 };
const passed = [];

for (const item of items) {
  const text = [
    (item.json.description || '').substring(0, 4000),
    item.json.location_text || '',
    item.json.job_title || ''
  ].join(' ');

  const hasKeep = KEEP.some(p => p.test(text));
  let rejectReason = null;

  if (!hasKeep) {
    for (const p of REJECT) {
      if (p.test(text)) {
        rejectReason = p.toString();
        break;
      }
    }
  }

  if (rejectReason) {
    const r = rejectReason.toLowerCase();
    if (/us|united.states/.test(r)) rc.usOnly++;
    else if (/eu|europe/.test(r)) rc.euOnly++;
    else if (/hybrid|onsite|office/.test(r)) rc.hybrid++;
    else if (/midnight|fixed.*hours/.test(r)) rc.timezone++;
    else rc.other++;
  } else {
    passed.push({ json: { ...item.json, has_keep_signal: hasKeep } });
  }
}

$workflow.staticData.rejectedCount = rc;
return passed;

const items = $input.all();
return items.map(item => ({
  json: {
    _job: item.json,
    _prompt: `You are filtering remote jobs for Jerry, who lives in Taiwan.

The most important rule: Jerry must be able to work this job while physically based in Taiwan.

Do not pass the job only because it says "remote."

Reject the job if it requires the worker to live in the US, Canada, UK, EU, Europe, Australia, or any specific country outside Taiwan.
Reject the job if it requires local work authorization outside Taiwan.
Reject the job if it is hybrid, onsite, or remote within one country only.
Reject the job if it requires fixed working hours that would force Jerry to work through the night in Taiwan (e.g., fixed US/EU business hours).

Keep the job only if one of these is true:
- The job says worldwide remote.
- The job says work from anywhere.
- The job says global remote.
- The job says APAC remote.
- The job allows international contractors.
- The job accepts people based anywhere.
- The company hires through EOR, Deel, Remote.com, Oyster, or contractor agreement.

Return JSON only, no explanation outside the JSON:
{
  "taiwan_eligible": "yes/no/unclear",
  "reason": "short reason",
  "location_risk": "low/medium/high",
  "timezone_risk": "low/medium/high",
  "contractor_possible": "yes/no/unclear",
  "decision": "keep/reject/manual_check"
}

Job Title: ${item.json.job_title}
Company: ${item.json.company}
Location: ${item.json.location_text}

Job post:
${(item.json.description || '').substring(0, 3500)}`
  }
}));

const items = $input.all();

return items.map(item => {
  const d = item.json;
  const originalJob = d._job || {};
  const aiResponse = d.content || [];

  let aiResult = {
    taiwan_eligible: 'unclear',
    reason: 'Could not parse AI response',
    location_risk: 'medium',
    timezone_risk: 'medium',
    contractor_possible: 'unclear',
    decision: 'manual_check'
  };

  try {
    let text = '';
    if (Array.isArray(aiResponse) && aiResponse[0] && aiResponse[0].text) {
      text = aiResponse[0].text;
    } else if (typeof aiResponse === 'string') {
      text = aiResponse;
    } else if (d.text) {
      text = d.text;
    }
    const match = text.match(/\{[\s\S]*?\}/);
    if (match) {
      const parsed = JSON.parse(match[0]);
      aiResult = {
        taiwan_eligible: parsed.taiwan_eligible || 'unclear',
        reason: parsed.reason || '',
        location_risk: parsed.location_risk || 'medium',
        timezone_risk: parsed.timezone_risk || 'medium',
        contractor_possible: parsed.contractor_possible || 'unclear',
        decision: parsed.decision || 'manual_check'
      };
    }
  } catch(e) {}

  return {
    json: {
      ...originalJob,
      taiwan_eligible: aiResult.taiwan_eligible,
      taiwan_reason: aiResult.reason,
      location_risk: aiResult.location_risk,
      timezone_risk: aiResult.timezone_risk,
      contractor_possible: aiResult.contractor_possible,
      ai_decision: aiResult.decision
    }
  };
});

const items = $input.all();

const ASYNC_HIGH = [/\basync\b/i, /\basynchronous\b/i, /\bno\s*meetings?\b/i, /\blow\s*meeting\s*culture\b/i, /\bwork\s*across\s*time\s*zones?\b/i];
const ASYNC_MED = [/\bflexible\s*hours?\b/i, /\bflexible\s*schedule\b/i, /\bflexible\s*working\b/i, /\bdistributed\s*team\b/i, /\bremote[\s-]?first\b/i, /\bfully\s*distributed\b/i];
const ASYNC_LOW = [/\bremote\b/i, /\bwork\s*from\s*home\b/i];
const REJECT_ASYNC = [/\bstrict\s*9\s*(to|-)\s*5\b/i, /\bdaily\s*live\s*calls?\s*required\b/i, /\bmust\s*overlap\s*full\s*business\s*day\b/i, /\bfixed\s*(us|est|pst|cst|cet)\s*hours?\b/i, /\b9am[\s-]5pm\s*(est|pst|cst|cet)\s*required\b/i];

return items.map(item => {
  const text = (item.json.description || '').substring(0, 4000);

  const rejected = REJECT_ASYNC.some(p => p.test(text));
  const asyncLevel = rejected ? 'rejected' :
    ASYNC_HIGH.some(p => p.test(text)) ? 'high' :
    ASYNC_MED.some(p => p.test(text)) ? 'medium' :
    ASYNC_LOW.some(p => p.test(text)) ? 'low' : 'unknown';

  return { json: { ...item.json, async_level: asyncLevel, _async_rejected: rejected } };
}).filter(i => !i.json._async_rejected);

const items = $input.all();

function score(job) {
  let s = 0;
  const text = [(job.description || '').substring(0,4000), job.location_text || '', job.job_title || ''].join(' ');

  // Taiwan eligibility (40 pts max)
  if (job.taiwan_eligible === 'yes') {
    if (/worldwide|global\s*remote|work\s*from\s*anywhere|anywhere|contractor|deel|oyster|eor/i.test(text)) s += 40;
    else if (/apac/i.test(text)) s += 30;
    else s += 20;
  } else if (job.taiwan_eligible === 'unclear') {
    s += 20;
  }

  // Async fit (25 pts max)
  if (job.async_level === 'high') s += 25;
  else if (job.async_level === 'medium') s += 20;
  else if (/distributed\s*team|remote[\s-]?first/i.test(text)) s += 15;
  else s += 10;

  // Role fit (25 pts max)
  const title = job.job_title.toLowerCase();
  if (/data\s*(analyst|scientist)|bi\s*analyst|business\s*intelligence|marketing\s*analyst|performance\s*marketing|growth\s*analyst|ai\s*marketing|ai\s*automation|martech|analytics\s*engineer/i.test(title)) s += 25;
  else if (/analyst|data|marketing|automation|ai|growth|intelligence/i.test(title)) s += 15;

  // Salary (10-25 pts)
  const sal = job.salary || '';
  const nums = sal.match(/(\d[\d,]*)/g);
  if (nums && nums.length > 0) {
    const maxNum = Math.max(...nums.map(n => parseInt(n.replace(/,/g,''))));
    if (maxNum >= 100000) s += 25;
    else if (maxNum >= 5000) s += 25;
    else if (maxNum >= 3000) s += 15;
    else s += 10;
  } else if (sal) s += 10;

  return Math.min(s, 100);
}

function categorize(title) {
  title = title.toLowerCase();
  if (/data\s*scientist|machine\s*learning|ml\s*engineer/i.test(title)) return 'Data Science';
  if (/bi\s*analyst|business\s*intelligence|analytics\s*engineer/i.test(title)) return 'BI & Analytics';
  if (/marketing\s*analyst|performance\s*marketing|growth\s*analyst/i.test(title)) return 'Marketing Analytics';
  if (/ai\s*(marketing|automation|workflow)|martech/i.test(title)) return 'AI / Automation';
  if (/data\s*analyst/i.test(title)) return 'Data Analytics';
  if (/marketing/i.test(title)) return 'Marketing';
  return 'Other';
}

function whyFit(job, sc, cat) {
  const parts = [`Score ${sc}/100`, `Category: ${cat}`, `Taiwan: ${job.taiwan_eligible}`, `Async: ${job.async_level}`];
  if (job.has_keep_signal) parts.push('Has worldwide/contractor signal');
  if (job.contractor_possible === 'yes') parts.push('Contractor role possible');
  if (job.location_risk === 'low') parts.push('Low location risk');
  return parts.join(' | ');
}

return items.map(item => {
  const sc = score(item.json);
  const cat = categorize(item.json.job_title);
  return { json: { ...item.json, score: sc, role_category: cat, why_good_fit: whyFit(item.json, sc, cat), application_status: 'New', notes: '', decision: sc >= 85 ? 'Apply Now' : sc >= 70 ? 'Review' : 'Skip' } };
});

const items = $input.all();
const originals = $('Score and Categorize').all();

return items.map((item, i) => {
  let coverLetter = '';
  try {
    const content = item.json.content;
    if (Array.isArray(content) && content[0] && content[0].text) {
      coverLetter = content[0].text;
    }
  } catch(e) {}

  const orig = originals.find(o => o.json.job_url === item.json._job?.job_url) || originals[i] || { json: {} };
  const job = orig.json;

  const alertText = `🚨 HIGH SCORE JOB ALERT\n\n📌 ${job.job_title}\n🏢 ${job.company}\n⭐ Score: ${job.score}/100\n🌏 Taiwan: ${job.taiwan_eligible} (${job.taiwan_reason || ''})\n⏰ Async: ${job.async_level}\n📍 Location Risk: ${job.location_risk}\n💰 Salary: ${job.salary || 'Not listed'}\n\n${job.job_url}\n\n✅ Why it fits Jerry:\n${job.why_good_fit}`;

  return { json: { ...job, cover_letter: coverLetter, alert_text: alertText } };
});

const allItems = $input.all();
const today = new Date().toISOString().split('T')[0];

// Filter to today's jobs
const todayJobs = allItems.filter(item => {
  const d = item.json.date_found || '';
  return d.startsWith(today);
}).map(i => i.json).sort((a,b) => (b.score || 0) - (a.score || 0));

const topJobs = todayJobs.filter(j => j.decision !== 'Skip').slice(0, 10);
const manualCheck = todayJobs.filter(j => j.taiwan_eligible === 'unclear' && (j.score || 0) >= 70);
const rc = $workflow.staticData.rejectedCount || { usOnly: 0, euOnly: 0, hybrid: 0, timezone: 0, other: 0 };

if (todayJobs.length === 0) {
  return [{ json: { skip_digest: true, message: 'No qualifying jobs found today.' } }];
}

let html = `<h2>📋 Daily Taiwan Eligible Async Remote Jobs — ${today}</h2>`;
html += `<p><strong>Found ${todayJobs.length} qualifying jobs today</strong></p>`;

html += '<h3>🏆 Top Jobs Today</h3>';

if (topJobs.length === 0) {
  html += '<p>No jobs scored 70+ today.</p>';
} else {
  topJobs.forEach((job, i) => {
    html += `<hr><h4>${i+1}. ${job.job_title}</h4>`;
    html += `<p><strong>Company:</strong> ${job.company}</p>`;
    html += `<p><strong>Score:</strong> ${job.score}/100</p>`;
    html += `<p><strong>Taiwan Eligible:</strong> ${job.taiwan_eligible} — ${job.taiwan_reason || ''}</p>`;
    html += `<p><strong>Async Level:</strong> ${job.async_level}</p>`;
    html += `<p><strong>Timezone Risk:</strong> ${job.timezone_risk}</p>`;
    html += `<p><strong>Location Risk:</strong> ${job.location_risk}</p>`;
    html += `<p><strong>Salary:</strong> ${job.salary || 'Not listed'}</p>`;
    html += `<p><strong>Role Category:</strong> ${job.role_category}</p>`;
    html += `<p><strong>Why it fits Jerry:</strong> ${job.why_good_fit}</p>`;
    html += `<p><a href="${job.job_url}">🔗 Apply Now</a></p>`;
  });
}

if (manualCheck.length > 0) {
  html += '<h3>⚠️ Manual Check Required</h3>';
  html += `<p>Taiwan eligibility is unclear but score is high for ${manualCheck.length} job(s):</p><ul>`;
  manualCheck.forEach(j => {
    html += `<li><strong>${j.job_title}</strong> at ${j.company} (Score: ${j.score}) — <a href="${j.job_url}">View</a></li>`;
  });
  html += '</ul>';
}

html += '<h3>❌ Rejected Summary</h3>';
html += `<ul>
<li>US Only: ${rc.usOnly}</li>
<li>EU Only: ${rc.euOnly}</li>
<li>Hybrid / Not Fully Remote: ${rc.hybrid}</li>
<li>Timezone Risk (fixed hours): ${rc.timezone}</li>
<li>Other Restrictions: ${rc.other}</li>
</ul>`;

html += '<hr><p><em>Generated by Daily Taiwan Eligible Async Remote Job Hunter</em></p>';

return [{ json: { html, subject: `Daily Taiwan Jobs — ${topJobs.length} top jobs today (${today})`, jobCount: todayJobs.length, skip_digest: false } }];
